"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[598],{4598:(e,t,n)=>{n.d(t,{A3:()=>u,rR:()=>y,KD:()=>m}),n(8144);var i=n(4169),a=n(8007),o=n(7002),s=n(1055),r=n(6024),l=n(4618),d=n(8999),c=n(7033),h=n(4714);let m=[{title:"Welcome.yml",date:"5 November 2025",displayDate:"5th November 2025",time:"2:45 PM to 5:00 PM",location:"SV Auditorium, Central Building, Heritage Institute of Technology",type:"Tech Talk & Extempore",cardDescription:"Dive into an afternoon of innovation and inspiration with the ACM HITK Student Chapter! Experience a power-packed Tech Talk by AWS professionals, get introduced to the world of ACM through an interactive orientation session, and witness ideas come alive in a thrilling Extempore showdown on cutting-edge tech themes — all leading up to an exciting valedictory celebration honoring the finest minds on campus",description:'<p>\uD83D\uDE80 The cloud is calling — are you ready to answer? \uD83D\uDE80</p>\n\n<div class="space-y-4">\n  <div>\n    <h3 class="text-lg font-semibold mb-2">Event Details</h3>\n    <ul class="space-y-1">\n      <li><strong>Date:</strong> November 5, 2025 (Wednesday)</li>\n      <li><strong>Time:</strong> 2:45 PM to 5:00 PM (Be seated by 2:45 PM sharp!)</li>\n      <li><strong>Venue:</strong> SV Auditorium, Central Building, Heritage Institute of Technology</li>\n      <li><strong>Speakers:</strong></li>\n      <ul class="list-disc pl-6 space-y-1">\n        <li>Mr. Bubai Bal – Solutions Architect, AWS India</li>\n        <li>Mr. Ritwik Ray – Partner Success Manager, AWS India & SAARC</li>\n      </ul>\n      <li><strong>Eligibility:</strong> Open to all students of Heritage Institute of Technology</li>\n    </ul>\n  </div>\n\n  <div>\n    <h3 class="text-lg font-semibold mb-2">Schedule</h3>\n    <div class="space-y-2">\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">2:45 PM – 2:55 PM: Inaugural Address & Welcome Note</h4>\n        <p class="text-sm text-muted-foreground">Opening remarks by the Faculty Sponsor and the ACM HITK Core Team</p>\n      </div>\n\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">2:55 PM – 4:00 PM: Technical Session – “From Cloud to AI: How Technology Shapes the Future”</h4>\n        <p class="text-sm text-muted-foreground">An engaging tech talk by AWS professionals – Mr. Bubai Bal and Mr. Ritwik Ray. Discover how cloud computing and AI are revolutionizing industries and shaping tomorrow’s digital innovators.</p>\n      </div>\n\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">4:00 PM – 4:15 PM: Orientation Session – Kickstart Your Journey with ACM HITK</h4>\n        <p class="text-sm text-muted-foreground">A short orientation for first-year students introducing the ACM HITK Student Chapter and its initiatives in fostering computing excellence.</p>\n      </div>\n\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">4:15 PM – 4:45 PM: Unscripted Tech – Extempore Round</h4>\n        <p class="text-sm text-muted-foreground">\n          A thrilling extempore event where innovation meets improvisation! The top 6 finalists, selected from the preliminary round, will speak spontaneously on surprise tech topics — showcasing creativity, confidence, and clarity.\n        </p>\n      </div>\n\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">4:45 PM – 5:00 PM: Valedictory & Prize Distribution</h4>\n        <p class="text-sm text-muted-foreground">Celebrating the brightest minds and rewarding the most inspiring voices of creativity and tech brilliance.</p>\n      </div>\n    </div>\n\n    <h3 class="text-lg font-semibold mb-2">Prizes & Goodies</h3>\n    <ul class="list-disc pl-5 space-y-1">\n      <li>Exciting prizes for top performers of “Unscripted Tech”</li>\n      <li>E-Certificates and MAR Points for participants</li>\n      <li>An opportunity to network with AWS professionals and ACM HITK members</li>\n    </ul>\n  </div>\n\n  <div class="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg">\n    <h3 class="font-semibold text-blue-700 dark:text-blue-300 mb-2">Important Note</h3>\n    <p class="text-sm text-blue-600 dark:text-blue-200">\n      Seats are limited and allocated on a first-come, first-served basis. Please arrive early to secure your seat. \n      <br>\n      The event is open to all students of Heritage Institute of Technology.\n    </p>\n  </div>\n</div>\n',registration_link:"https://forms.gle/u3naFpvhTnQ91j1X7",registration_deadline:"2025-11-04T23:59:00",speaker:"Mr. Bubai Bal & Mr. Ritwik Ray",capacity:"Limited seats available",status:"open",bannerImage:"/Events/Welcome-yml.png",photos:[]},{title:"Innovista'25",date:"January 2026",displayDate:"January 2026",time:"To be announced",location:"To be announced",type:"Technical Fest",cardDescription:"A flagship inter-college fest by ACM HITK, celebrating creativity, computation, and collaboration. Featuring an inspiring ACM India Eminent Speaker Session and SparkTank, a thrilling idea-pitching challenge that transforms bold visions into real-world innovation.",speaker:"To be announced",capacity:"To be announced",status:""}],u=[{title:"Put On Your Computing Cap!",date:"2025-09-01",time:"1:00 PM to 3:30 PM",location:"CME 108, Heritage Institute of Technology",type:"Tech Talk & Quiz",cardDescription:"An electrifying event combining a technical session on HCI and an interactive quiz to test wit, logic, and computing knowledge.",description:'<p>\uD83D\uDEA8 The stage is set, the buzz is real, and the world of computation is calling YOU! \uD83D\uDEA8</p>\n\n<div class="space-y-4">\n  <div>\n    <h3 class="text-lg font-semibold mb-2">Event Details</h3>\n    <ul class="space-y-1">\n      <li><strong>Date:</strong> September 1, 2025 (Monday)</li>\n      <li><strong>Time:</strong> 1:00 PM to 3:30 PM (Be seated by 12:50 PM sharp!)</li>\n      <li><strong>Venue:</strong> CME 108, Heritage Institute of Technology</li>\n      <li><strong>Speakers:</strong></li>\n      <ul class="list-disc pl-6 space-y-1">\n        <li>Prof. (Dr.) Nabendu Chaki – Professor & Former Head, CSE, University of Calcutta; Dean (Acting), Faculty of Engineering & Technology, University of Calcutta; Chair, ACM Professional Chapter, Kolkata</li>\n        <li>Mr. Snehasis Banerjee – Lead Research Scientist, TCS Research; Guest Faculty, IIIT-G; Treasurer, ACM Professional Chapter, Kolkata</li>\n      </ul>\n      <li><strong>Eligibility:</strong> Open to all students of Heritage Institute of Technology</li>\n    </ul>\n  </div>\n\n  <div>\n    <h3 class="text-lg font-semibold mb-2">Schedule</h3>\n    <div class="space-y-2">\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">1:00 PM – 2:15 PM: Technical Session</h4>\n        <p class="text-sm text-muted-foreground">Tech Talk – “Using Formal Methods for Dialog Design in HCI” by Prof. (Dr.) Nabendu Chaki</p>\n      </div>\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">2:15 PM – 2:30 PM: Break</h4>\n        <p class="text-sm text-muted-foreground">Short intermission</p>\n      </div>\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">2:30 PM – 3:15 PM: Interactive Quiz – “Prashna Bichitra”</h4>\n        <p class="text-sm text-muted-foreground">Hosted by Mr. Snehasis Banerjee; an audio-visual quiz testing logic, wit, and speed</p>\n      </div>\n      <div class="bg-muted/50 p-3 rounded-lg">\n        <h4 class="font-medium">3:15 PM – 3:30 PM: Valedictory & Prize Distribution</h4>\n        <p class="text-sm text-muted-foreground">Closing remarks and prizes for top performers</p>\n      </div>\n    </div>\n<h3 class="text-lg font-semibold mb-2">Prizes & Goodies</h3>\n<ul class="list-disc pl-5 space-y-1">\n  <li>Exciting prizes and goodies for top performers</li>\n  <li>A chance to learn, compete, and connect with industry professionals</li>\n  <li>Bragging rights!</li>\n</ul>\n\n  </div>\n\n  <div class="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg">\n    <h3 class="font-semibold text-blue-700 dark:text-blue-300 mb-2">Important Note</h3>\n    <p class="text-sm text-blue-600 dark:text-blue-200">\n      Seats are limited and allocated on a first-come, first-served basis. Registration does not guarantee a seat — please arrive early to secure yours.\n    </p>\n  </div>\n</div>\n',speaker:"Prof. (Dr.) Nabendu Chaki & Mr. Snehasis Banerjee",capacity:"Limited seats available",status:"closed",registration_link:"https://forms.gle/2rqNc18uXhCfox2x9",registration_deadline:"2025-08-31T23:59:00",bannerImage:"/Events/Put-On-Your-Computing-Cap.jpeg",photos:[]},{title:"Program Paradox",date:"2025-08-08",time:"2:30 PM to 5:00 PM",location:"The Heritage Academy Auditorium",type:"Workshop",cardDescription:"An interactive workshop session exploring the fascinating concept of the Halting Problem in computer science.",description:'\n        <p>Ever wondered if it\'s possible to design a program that can predict what another program will do? At first glance, it might sound like a thrilling possibility—but as you\'ll discover, there\'s a fascinating twist.</p>\n        \n        <div class="space-y-4">\n          <div>\n            <h3 class="text-lg font-semibold mb-2">Event Details</h3>\n            <ul class="space-y-1">\n              <li><strong>Date:</strong> August 8, 2025</li>\n              <li><strong>Time:</strong> 2:30 PM to 5:00 PM</li>\n              <li><strong>Venue:</strong> The Heritage Academy Auditorium</li>\n              <li><strong>Speakers:</strong> Mohak Sarkar & Aryan Ghosh</li>\n              <li><strong>Eligibility:</strong> Open to all students, staff, and faculty of HITK</li>\n            </ul>\n          </div>\n  \n          <div>\n            <h3 class="text-lg font-semibold mb-2">Schedule</h3>\n            <div class="space-y-2">\n              <div class="bg-muted/50 p-3 rounded-lg">\n                <h4 class="font-medium">2:30 PM - 3:00 PM: Introduction</h4>\n                <p class="text-sm text-muted-foreground">Introduction to the Halting Problem</p>\n              </div>\n              <div class="bg-muted/50 p-3 rounded-lg">\n                <h4 class="font-medium">3:00 PM - 4:00 PM: Interactive Workshop</h4>\n                <p class="text-sm text-muted-foreground">Dive into the Halting Problem with hands-on activities</p>\n              </div>\n              <div class="bg-muted/50 p-3 rounded-lg">\n                <h4 class="font-medium">4:00 PM - 4:45 PM: Quiz Showdown</h4>\n                <p class="text-sm text-muted-foreground">Test your knowledge and win exciting prizes</p>\n              </div>\n              <div class="bg-muted/50 p-3 rounded-lg">\n                <h4 class="font-medium">4:45 PM - 5:00 PM: Valedictory</h4>\n                <p class="text-sm text-muted-foreground">Wrap up the event with a final thought.</p>\n              </div>\n            </div>\n            <h3 class="text-lg font-semibold mb-2">Prizes & Goodies</h3>\n            <ul class="list-disc pl-5 space-y-1">\n              <li>Exclusive rewards for top performers</li>\n              <li>Networking opportunities</li>\n            </ul>\n          </div>\n  \n          <div class="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg">\n            <h3 class="font-semibold text-blue-700 dark:text-blue-300 mb-2">What to Bring</h3>\n            <ul class="list-disc pl-5 space-y-1 text-blue-600 dark:text-blue-200">\n              <li>Your mobile phone</li>\n              <li>Stable internet connection (for quiz round)</li>\n              <li>Enthusiasm to learn and compete!</li>\n            </ul>\n            <p class="mt-3 text-sm text-blue-600/80 dark:text-blue-300/80">\n              <em>Registration is free but mandatory. Limited seats available!</em><br />\n              <strong>Registration closes:</strong> August 6th, 11:59 PM IST\n            </p>\n          </div>\n        </div>\n      ',speaker:"Mohak Sarkar & Aryan Ghosh",capacity:"Limited seats available",status:"",registration_link:"https://forms.gle/bdc6NkxPgExRPEsw5",registration_deadline:"2025-08-06T23:59:00",bannerImage:"/Events/Program-Paradox-0.png",photos:[]},{title:"The celebrated birthday problem",date:"August 8, 2024",type:"Seminar",cardDescription:"What is the chance that among a group of friends, at least 2 of them have the same birthday? This is the celebrated birthday problem, which connects many seemingly disparate problems both within and beyond mathematics.",description:'"Birthday Paradox and its Algorithmic Applications" by Dr. Bhaswar B.\n  Bhattacharya Abstract: What is the chance that among a group of friends, at least\n  2 of them have the same birthday? This is the celebrated birthday problem, which\n  connects many seemingly disparate problems both within and beyond\n  mathematics. In this talk, we will discuss different variations of the birthday\n  paradox and their applications in computer science, specifically distributional\n  property testing and computation of discrete logarithms. (ii)"God Forever\n  Geometrizes" by Dr. Bhargab B. Bhattacharya Abstract: As Plato observed, nature\n  is governed by the eternal laws of geometry. In this talk, we show some\n  fascinating examples to demonstrate how geometry manifests in physics and in\n  ancient architectures. Next, from the perspective of computational geometry, we\n  demystify the problem of cutting a pizza or a sandwich. Finally, we demonstrate\n  how 2D point-set polygonization yields assistance to differently-abled persons.',attendees:82,speaker:"Dr. Bhaswar B. Bhattacharya",location:"THA Hall, Heritage Academy",photos:[]},{title:"God Forever Geometrizes",date:"August 8, 2024",type:"Seminar",cardDescription:"As Plato observed, nature is governed by the eternal laws of geometry.",description:"As Plato observed, nature is governed by the eternal laws of geometry.\n  In this talk, we show some fascinating examples to demonstrate how geometry\n  manifests in physics and in ancient architecture. Next, from the perspective of\n  computational geometry, we demystify the problem of cutting a pizza or a\n  sandwich. Finally, we demonstrate how 2D point-set polygonization yields\n  assistance to differently-abled persons.",attendees:82,speaker:"Dr. Bhargab B. Bhattacharya",location:"THA Hall, Heritage Academy",photos:[]},{title:" Technical Debt in Machine Learning Systems",date:"September 4, 2024",type:"Seminar",cardDescription:"In the context of software development, technical debt relates to the cost of refactoring or rework in the future that arises out of the prioritization of immediate expedience over long-term design.",description:"In the context of software development, technical debt relates to the\n  cost of refactoring or rework in the future that arises out of the prioritization of\n  immediate expedience over long-term design. This talk discusses the accrual\n  and management of technical debt in machine learning systems.",attendees:36,speaker:"Uday Shaw",location:"ICT Building",photos:[]},{title:"Evaluation of Large Language Models: The Good, The Bad, and The\n  Opportunities",date:"Auguest 4, 2023",type:"Seminar",cardDescription:"The recent sensation ChatGPT, powered by large language models (LLM) can be used to mimic a human conversationalist, ChatGPT is versatile.",description:" The recent sensation ChatGPT, powered by large language models\n  (LLM) can be used to mimic a human conversationalist, ChatGPT is versatile.\n  Among countless examples, it can write and debug computer programs,\n  compose music, teleplays, fairy tales, and student essays, answer test questions,\n  etc. It is an open issue: How can deep learning be incorporated to make it more\n  efficient and reduce its drawbacks?",attendees:100,speaker:"Dr Tanmoy Chakraborty",location:"SV Auditorium, CB Block, HITK",photos:[]},{title:"Semiconductors to AI: Shaping Our Digital Future",date:"August 8, 2023",type:"Seminar",cardDescription:"The talk begins with the evolution of computers and the synergistic roles played by the twin disciplines of electronics engineering and computer science and how that synergy brought computers to its all-pervasive present state.",description:" The talk begins with the evolution of computers and the synergistic\n  roles played by the twin disciplines of electronics engineering and computer\n  science and how that synergy brought computers to its all-pervasive present\n  state. After showing the spectacular growth of semiconductor devices and the\n  ubiquitous nature of this technology, the talk hints at how this growth fuelled\n  renewed interest in artificial intelligence and machine learning and the revolution\n  that we all are currently witnessing because of that. In particular, the discourse\n  shows the current advances in natural language processing and its potential\n  impact on our everyday life. The talk concludes by showing some of those\n  impacts of AI/ML and their possible far-reaching effects on our society ? both\n  good and adverse.",attendees:23,speaker:"",location:"",photos:[]},{title:"Recommender Systems: Your Fairy Godmother of Choices",date:"September 27, 2023",type:"Seminar",cardDescription:"Have you ever wondered how online platforms magically suggest products, movies, or music that seem tailor-made for you? It's not magic; it's the power of Recommender Systems (RS). Join us in this informative and hands-on session as we demystify the world of RS and learn how these digital fairy godmothers work their magic to enhance user experiences. In the first part of our talk, we'll dive deep into the world of Recommender Systems, shedding light on their applications, workings, and various types. You'll gain a comprehensive understanding of the foundations of RS, setting the stage for your journey into the world of personalized recommendations. In the second part, get ready to put your knowledge to the test as we guide you through the process of building a simple RS model. We'll use a user-friendly framework, making it accessible to everyone. We'll share practical tips and best practices to help you fine-tune your RS and ensure it provides meaningful recommendations. Join us for this exciting journey into the world of Recommender Systems, and discover how they can be your own fairy godmother of choices, making every digital interaction feel like it was designed just for you.",description:"Have you ever wondered how online platforms magically suggest\n  products, movies, or music that seem tailor-made for you? It's not magic; it's the\n  power of Recommender Systems (RS). Join us in this informative and hands-on\n  session as we demystify the world of RS and learn how these digital fairy\n  godmothers work their magic to enhance user experiences. In the first part of our\n  talk, we'll dive deep into the world of Recommender Systems, shedding light on\n  their applications, workings, and various types. You'll gain a comprehensive\n  understanding of the foundations of RS, setting the stage for your journey into\n  the world of personalized recommendations. In the second part, get ready to put\n  your knowledge to the test as we guide you through the process of building a\n  simple RS model. We'll use a user-friendly framework, making it accessible to\n  everyone. We'll share practical tips and best practices to help you fine-tune your\n  RS and ensure it provides meaningful recommendations. Join us for this exciting\n  journey into the world of Recommender Systems, and discover how they can be\n  your own fairy godmother of choices, making every digital interaction feel like it\n  was designed just for you.",attendees:47,speaker:"Ashmi Banerjee",location:"CB 504, CB Block, HITK",photos:[]},{title:"Computability and Complexity Theory - A Brief Introduction",date:"December 14, 2023",type:"Workshop",cardDescription:"What does it mean for something to be computable? What are some of the mathematical properties of general-purpose computers? What are their limitations? These are typical questions that are of interest to computability theorists.",description:"What does it mean for something to be computable? What are some of\n  the mathematical properties of general-purpose computers? What are their\n  limitations? These are typical questions that are of interest to computability\n  theorists. In this talk, we shall discuss answers to some of these questions and\n  more. We shall also discuss some common results of Complexity Theory, by\n  applying some space/time restriction on our model of computation.",attendees:20,speaker:"",location:"",photos:[]},{title:"Brain Research - Implications in Science, Engineering and Society",date:"February 9, 2024",type:"Seminar",cardDescription:"The brain is one of the most connected organs of an organism. It directly connects to all the organs through a network of neurons. The brain interacts with the body through a combination of electrochemical and chemical processes. The brain also controls the body indirectly through hormones and neuropeptides. Similarly, the body also controls the brain by modulating its function through indirect and direct means.",description:"The brain is one of the most connected organs of an organism. It\n  directly connects to all the organs through a network of neurons. The brain\n  interacts with the body through a combination of electrochemical and chemical\n  processes. The brain also controls the body indirectly through hormones and\n  neuropeptides. Similarly, the body also controls the brain by modulating its\n  function through indirect and direct means. Besides, the brain is at the center of\n  self-awareness and societal organization. All these require highly complex,\n  real-time data processing and decision-making system. How does the brain\n  manage it? Although the answer is not as simple as the question, neuroscience\n  research does, however, clarify a great deal about controlling, modifying, and\n  mimicking some of the brain functions in artificial systems. Understanding the\n  brain involves a range of disciplines ranging from genetics and psychology to\n  computer science.",attendees:45,speaker:"",location:"",photos:[]},{title:"Solving the Classic Distinct Element Problem with a Strikingly Simple Algorithm that Captivated Donald Knuth",date:"April 15, 2024",type:"Workshop",cardDescription:"We will present a very simple streaming algorithm on F_0 estimation that also caught the eye of Donald E. Knuth.",description:'We will present a very simple streaming algorithm on F_0 estimation\n  that also caught the eye of Donald E. Knuth. In a recent article, Donald E. Knuth\n  started with the following two paragraphs: "Sourav Chakraborty, N. V.\n  Vinodchandran, and Kuldeep S. Meel have recently proposed an interesting\n  algorithm for the following problem: A stream of elements (a1, a2,..., am) is\n  input, one at a time, and we want to know how many of them are distinct. In\n  other words, if A = {a1, a2,..., am} is the set of elements in the stream, with\n  multiplicities ignored, we want to know |A|, the size of that set. But we don?t\n  have much memory; in fact, |A| is probably a lot larger than the number of\n  elements that we can hold in memory at any one time. What is a good strategy for\n  computing an unbiased estimate of |A|? Their algorithm is not only interesting, it\n  is extremely simple. Furthermore, it?s wonderfully suited to teaching students\n  who are learning the basics of computer science. (Indeed, ever since I saw it, a\n  few days ago, I?ve been unable to resist trying to explain the ideas to just about\n  everybody I meet.) Therefore I?m pretty sure that something like this will\n  eventually become a standard textbook topic. This note is an initial\n  approximation to what I might write about it if I were preparing a textbook about\n  data streams."',attendees:15,speaker:"",location:"",photos:[]},{title:"Generative A.I. workshop",date:"April 16, 2024",type:"Workshop",cardDescription:"Understanding the broad view of Generative AI, Addressing the Fear, Types of Generative AI architectures, LLM and LIM, Building an AI tool (Using Hugging Face), QnA",description:"Program Overview 1. Understanding the broad view of Generative AI 2.\n  Addressing the Fear 3. Types of Generative AI architectures 4. LLM and LIM 5.\n  Building an AI tool (Using Hugging Face) 6. QnA",attendees:10,speaker:"",location:"",photos:[]}];var p=n(8942),g=n(6122);d.A,p.A,g.A,d.A,p.A,g.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,p.A,d.A,l.A,g.A,p.A,p.A,d.A,p.A,d.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,p.A,d.A,p.A,d.A,p.A,d.A,l.A,p.A,d.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,p.A,d.A,p.A,d.A,l.A,g.A,p.A,d.A,p.A,d.A,g.A,p.A,d.A,g.A,p.A,d.A,g.A,p.A,d.A,g.A,p.A,d.A,p.A,d.A,l.A,g.A,p.A,d.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,p.A,d.A,l.A,i.A,a.A,o.A,s.A,r.A,l.A,d.A,c.A,h.A;let y=[{name:"Reshma Roychoudhuri",image:"/Reshma-Roychoudhuri.jpeg",role:"Assistant Professor, Department of Computer Science and Engineering, HITK",testimonial:"ACM will always have a special place in my heart. The passion and hardwork of the past and current teams, and the quality of the talks sets it apart. I am hoping that the chapter increases it's reach and promotes inclusivity even more in the coming years."},{name:"Swarnadeep Saha",image:"/Swarnadeep-Saha.jpg",role:"Mtech(CSE) Student at IIIT Hyderabad",testimonial:"Learned how to manage different aspects of event organization. Learned how to work closely with professors and other fellow students."},{name:"Rajarshi Saha",image:"/Rajarshi-Saha.jpeg",role:"Associate Software Engineer, EY GDS",testimonial:"I had a great time being a part of the HITK ACM Student Chapter, and I hope the current members enjoy their journey and gain valuable experiences during their tenure. Take the chapter to greater heights, and organize as many events as possible. Wishing you guys all the best!"},{name:"Upasana Roy",image:"/Upasana-Roy.jpg",role:"SDE 1, Cozeva - Applied Research Works India Private Limited",testimonial:"Being part of the HITK ACM Student Chapter was an incredible journey! Tech talks gave me the chance to interact with professors and researchers, to know the recent trends and developments in the industry and I even got to present my own ideas. From attending events to organizing events myself, the chapter helped me grow both technically and personally. If you’re a member, don’t hold back. Collaborate, lead, speak up, and make the most of every opportunity."},{name:"Devjit Sarkar",image:"/Devjit-Sarkar.jpg",role:"Summer Intern, Hyland",testimonial:"Being part of the HITK ACM Student Chapter was an overall positive and enriching experience. I had the opportunity to witness several inspiring talks and work alongside passionate peers. A fond memory that stands out is Brainstorm 2025, from collaboratively crafting challenging quiz questions to troubleshooting technical issues on the event day, the teamwork and energy were unforgettable. My advice to current members: stay curious, get involved, and make the most of every opportunity the chapter offers."}]}}]);